+fn identity(c: &Connection, row: &CorporateActionImportRow) -> AppResult<Option<(String, Value)>> {
+    if row.exchange != "NSE" || row.source != "NSE_API" || row.parse_status != "PARSED"
+        || !matches!(row.action_type.as_str(), "SPLIT" | "BONUS")
