+/// Event precedes the sole rename, so both bars must belong to the old alias.
+/// Never substitute a current-alias file or SQL underneath an existing binary.
+pub(super) fn trade_window(c:&Connection,folder:&Path,row:&CorporateActionImportRow)
+    ->AppResult<Option<(ScannedBar,ScannedBar)>> {
+    let Some((_,meta))=identity(c,row)? else { return Ok(None); };
+    let raw=row.symbol.as_deref().unwrap(); let date=row.ex_date.as_deref().unwrap();
+    let window=if folder.join("eod_data").join("NSE").join(format!("{raw}.eod")).exists() {
+        load_binary_trade_window(folder,raw,"NSE",date)?
+    } else if get_price_storage_mode(c)==PriceStorageMode::Hybrid {
+        load_sqlite_trade_window(c,raw,"NSE",date)?
+    } else { None };
+    let Some((previous,ex))=window else { return Ok(None); };
+    let rename=meta["edge"][2].as_str().unwrap_or("");
+    let today=chrono::Utc::now().with_timezone(&chrono::FixedOffset::east_opt(19800).unwrap()).date_naive();
+    if ensure_import_trade_window_ready(Some(&(previous.clone(),ex.clone())),date,today).is_err()
+        || previous.date.as_str()>=rename || ex.date.as_str()>=rename { return Ok(None); }
+    Ok(Some((previous,ex)))
+}
+
+fn evaluate(c:&Connection,folder:&Path,row:&CorporateActionImportRow)->AppResult<Option<Proof>> {
+    let Some((target,identity))=identity(c,row)? else { return Ok(None); };
+    if ensure_split_bonus_price_validation(c,row,false).is_err() { return Ok(None); }
+    let Some(scan)=load_latest_official_split_bonus_validation(c,row.id)? else { return Ok(None); };
+    if scan.symbol!=row.symbol || scan.exchange!=row.exchange { return Ok(None); }
+    let Some((previous,ex))=trade_window(c,folder,row)? else { return Ok(None); };
+    if scan.prev_trade_date.as_deref()!=Some(&previous.date) || scan.ex_trade_date.as_deref()!=Some(&ex.date)
+        || scan.prev_close.map(f64::to_bits)!=Some(previous.close.to_bits())
+        || scan.ex_open.map(f64::to_bits)!=Some(ex.open.to_bits())
+        || scan.ex_close.map(f64::to_bits)!=Some(ex.close.to_bits()) { return Ok(None); }
+    let database:String=c.query_row("SELECT file FROM pragma_database_list WHERE name='main'",[],|r|r.get(0)).map_err(|e|e.to_string())?;
+    Ok(Some(Proof {target,identity,scan:serde_json::to_value(scan).map_err(|e|e.to_string())?,
+        event:serde_json::json!({"id":row.id,"symbol":row.symbol,"isin":row.isin,"source":row.source,
+            "sourceFile":row.source_file,"purpose":row.purpose_raw,"date":row.ex_date,"recordDate":row.record_date,
+            "action":row.action_type,"factor":row.factor,"priceFactor":row.price_factor,"ratio":[row.ratio_num,row.ratio_den],
+            "face":[row.old_face_value,row.new_face_value],"cash":row.cash_amount}),
+        database:database.replace('/',"\\"),previous_date:previous.date,previous_close:previous.close}))
+}
+
+impl Proof {
+    pub(in crate::database) fn fingerprint(&self)->AppResult<String> {
+        Ok(digest(&serde_json::to_vec(self).map_err(|e|e.to_string())?))
+    }
+    pub(in crate::database) fn previous(&self)->(&str,f64) {(&self.previous_date,self.previous_close)}
+}
+
+pub(in crate::database) fn verified(c:&Connection,folder:&Path,row:&CorporateActionImportRow)->AppResult<Option<Proof>> {
+    if !has_table(c,"corporate_action_split_bonus_chain_proofs")? {return Ok(None);}
+    let stored=c.query_row("SELECT proof_json,fingerprint FROM corporate_action_split_bonus_chain_proofs WHERE import_id=?",
+        [row.id],|r|Ok((r.get::<_,String>(0)?,r.get::<_,String>(1)?))).optional().map_err(|e|e.to_string())?;
+    let Some((json,hash))=stored else {return Ok(None);};
+    let Ok(proof)=serde_json::from_str::<Proof>(&json) else {return Ok(None);};
+    let Some(current)=evaluate(c,folder,row)? else {return Ok(None);};
+    Ok(if proof==current && current.fingerprint()?==hash {Some(current)} else {None})
+}
+
+pub(super) fn has_decision(c:&Connection,id:i64)->AppResult<bool> {
+    c.query_row("SELECT EXISTS(SELECT 1 FROM corporate_action_import_decisions WHERE import_id=? AND decision_type=?)",
+        params![id,DECISION],|r|r.get(0)).map_err(|e|e.to_string())
+}
+
+pub(super) fn prepare(c:&Connection,folder:&Path,row:&CorporateActionImportRow)->AppResult<()> {
+    let Some(proof)=evaluate(c,folder,row)? else {
+        if has_decision(c,row.id)? {identity_recheck::recheck_pending_machine_identity(c,row)?;}
+        return Ok(());
+    };
+    let fingerprint=proof.fingerprint()?;
+    if row.review_status=="PENDING" && verified(c,folder,row)?.is_some() {return Ok(());}
+    c.execute("INSERT INTO corporate_action_split_bonus_chain_proofs(import_id,proof_json,fingerprint) VALUES(?,?,?)
+        ON CONFLICT(import_id) DO UPDATE SET proof_json=excluded.proof_json,fingerprint=excluded.fingerprint",
+        params![row.id,serde_json::to_string(&proof).map_err(|e|e.to_string())?,fingerprint]).map_err(|e|e.to_string())?;
+    c.execute("UPDATE corporate_action_imports SET review_status='PENDING',message=? WHERE id=? AND approved_corporate_action_id IS NULL",
+        params![format!("Verified historical event; adjustment owner NSE:{}; approval remains explicit.",proof.target),row.id]).map_err(|e|e.to_string())?;
+    let after=get_import_row(c,row.id)?;
+    record_corporate_action_import_decision(c,row,&after,DECISION,&format!("raw=NSE:{}; owner=NSE:{}; proof={fingerprint}",row.symbol.as_deref().unwrap_or(""),proof.target))
+}
+
+/// Route-scoped duplicate lookup: neither an issuer prefix nor a bare ISIN can
+/// link a financial record belonging to an unrelated symbol.
+pub(super) fn existing(c:&Connection,row:&CorporateActionImportRow,proof:&Proof)->AppResult<Option<i64>> {
+    let mut stmt=c.prepare("SELECT id,factor,ratio_num,ratio_den,old_face_value,new_face_value,cash_amount,isin
+        FROM corporate_actions WHERE exchange=? AND effective_date=? AND action_type=? AND symbol IN (?,?)").map_err(|e|e.to_string())?;
+    let rows=stmt.query_map(params![row.exchange,row.ex_date,row.action_type,row.symbol,proof.target],|r|Ok((r.get::<_,i64>(0)?,r.get::<_,f64>(1)?,
+        r.get::<_,Option<f64>>(2)?,r.get::<_,Option<f64>>(3)?,r.get::<_,Option<f64>>(4)?,r.get::<_,Option<f64>>(5)?,r.get::<_,Option<f64>>(6)?,r.get::<_,Option<String>>(7)?)))
+        .map_err(|e|e.to_string())?.collect::<Result<Vec<_>,_>>().map_err(|e|e.to_string())?;
+    if rows.is_empty(){return Ok(None);}
+    if rows.len()!=1 {return Err("Ambiguous existing adjustment for the verified rename route.".into());}
+    let r=&rows[0];
+    if row.factor!=Some(r.1) || (row.ratio_num,row.ratio_den,row.old_face_value,row.new_face_value,row.cash_amount,row.isin.as_deref())
+        !=(r.2,r.3,r.4,r.5,r.6,r.7.as_deref()) {return Err("Existing adjustment terms conflict with the verified rename route.".into());}
+    Ok(Some(r.0))
+}
